"""Save actual checkpoints and mechanical evidence to draft PR independently of chat.
Never invent language judgments, promote a model, or claim unseen/general ability.
"""
import pathlib,subprocess,json,hashlib,datetime,sys,torch
R=pathlib.Path(__file__).resolve().parents[1];E=R/'execution';REPO=R.parents[2]
def read(p):return json.loads(p.read_text())
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def run(args,**kw):return subprocess.run(args,cwd=REPO,check=True,**kw)
status=int(sys.argv[1]);torch.set_num_threads(1);cp=R/'continue-10000/checkpoint.pt';saved=torch.load(cp,map_location='cpu',weights_only=False) if cp.exists() else None;step=saved['step'] if saved else 0;counters=sorted({int(s['step']) for s in saved['optimizer']['state'].values()}) if saved else [];assert not saved or counters==[10000+step]
model=R/'continue-10000/model.js';new=E/'new-validation.json';old=E/'old-validation.json';mechanical=all(p.exists() for p in [new,old,E/'new-validation-js.json',E/'old-validation-js.json',E/'sampler-replay.json'])
record={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pipelineExitCode':status,'actualRetainedAdditionalUpdates':step,'requestedUpdates':10000,'optimizerCounters':counters,'completedTraining':step==10000,'mechanicalOutputsAvailable':mechanical,'languageAssessment':'Pending complete raw-output reading; no semantic score guessed','strictLanguageGateAssessed':False,'publicModelChanged':False,'testGenerated':False,'uncheckpointedPhysicalUpdatesUnknown':status!=0 and step<10000,'resumeCommand':'bash training/language/round25/execution/run.sh --resume' if step<10000 else None,'bestDevelopmentNllPerByte':saved['bestloss'] if saved else None,'selectedStep':saved['beststep'] if saved else None}
write(E/'mechanical-status.json',record)
(R/'MECHANICAL_STATUS.md').write_text('# Mechanical execution status — language review pending\n\n'+f"Actual retained additional optimizer updates: {step}/10000. Optimizer counters: {counters}. Pipeline exit: {status}. Mechanical outputs available: {mechanical}.\n\n"+'Checkpoint includes aligned model/AdamW/Torch RNG/private Python RNG. Raw old/new JSON retains every generated token and unedited character. Semantic/full-language judgment is pending actual complete reading; no score or gate pass is guessed. No public model/site replacement or TEST generation.\n')
files=[str(p.relative_to(REPO)) for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name not in ['automatic-publish.log','automatic-publish-complete.json']]
run(['git','add','--',*files]);run(['git','commit','-m',f'Save Round25 actual retained {step} updates and ungraded mechanical evidence']);commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip();run(['git','-c','pack.threads=1','push'])
pr=json.loads(subprocess.check_output(['gh','pr','view','--json','number'],cwd=REPO,text=True))['number']
body=f"Round25: add negative-only self-generated repeated-fourgram sequence loss coefficient0.1 every10updates; same teacherUL1.0, data and aligned Round11 parent as Round24. Actual retained updates {step}/10000; optimizer counters {counters}; best exposed-DEV NLL {record['bestDevelopmentNllPerByte']}; selected step {record['selectedStep']}; pipeline exit {status}. Checkpoint/optimizer/RNG and full training rollout trace saved at {commit}. Full semantic reading pending, no score guessed, no TEST generation or public replacement. See training/language/round25/MECHANICAL_STATUS.md."
run(['gh','api',f'repos/4k29/4k29/pulls/{pr}','--method','PATCH','--input','-'],input=json.dumps({'body':body}).encode(),stdout=subprocess.DEVNULL)
write(E/'automatic-publish-complete.json',dict(commit=commit,pr=pr,actualRetainedAdditionalUpdates=step,utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),languageReviewPending=True));print(json.dumps({'actualRetainedAdditionalUpdates':step,'savedCommit':commit,'pr':pr}),flush=True)
